INSERT INTO public.aquariums VALUES (1, '2026-09-01 10:00:00.000000', 'Aquário marinho misto com corais SPS (Acroporas) e LPS (Torches), substrato de aragonita viva e sump de 100L com skimmer potente.', 'Reef dos Sonhos 350L', 'MARINE', 350, 1);
