-- 4. Aquarium Notes
INSERT INTO public.aquarium_notes VALUES (1, 'Marcelo (Bamba Aqua)', 'Realizada checagem visual dos corais duros. Acropora millepora apresentando crescimento nas pontas. Skimmer limpo e regulado.', '2026-10-10 14:00:00.000000', '2026-10-10 14:00:00.000000', 'Avaliação Periódica do Reef', 1);
INSERT INTO public.aquarium_notes VALUES (2, 'Atendente Balcão', 'Cliente adquiriu dosadora Jebao 4 canais. Programada para dosar Kh, Cálcio e Magnésio de hora em hora.', '2026-10-10 14:00:00.000000', '2026-10-10 14:00:00.000000', 'Instalação de Bomba Dosadora', 1);
INSERT INTO public.aquarium_notes VALUES (3, 'Marcelo (Bamba Aqua)', 'Poda das Rotalas e replantio das mudas. Inseridas pastilhas de NPK no substrato próximo às raízes.', '2026-10-10 14:00:00.000000', '2026-10-10 14:00:00.000000', 'Poda Geral e Adubação', 4);
INSERT INTO public.aquarium_notes VALUES (4, 'Atendente Balcão', 'Cliente trouxe o refratômetro para aferição na loja. Calibrado com líquido de referência 35ppt.', '2026-10-10 14:00:00.000000', '2026-10-10 14:00:00.000000', 'Calibração de Refratômetro Óptico', 6);
INSERT INTO public.aquarium_notes VALUES (5, 'Marcelo (Bamba Aqua)', 'Realizado banho profilático com dip coral antes da colagem na rocha matriz.', '2026-10-10 14:00:00.000000', '2026-10-10 14:00:00.000000', 'Aclimatação de Coral Torch Gold', 7);
INSERT INTO public.aquarium_notes VALUES (6, 'Lucas Ferraz', 'Realizada TPA de 25% com água tratada com Prime e adicionadas 2 folhas secas de catappa.', '2026-10-10 14:00:00.000000', '2026-10-10 14:00:00.000000', 'Troca Parcial e Adição de Folhas de Amendoeira', 9);

-- 5. Water Parameter Tests
INSERT INTO public.water_parameter_tests VALUES (1, 0, 430, 'Corais expandindo pólipos com vitalidade máxima. Peixes ativos e comendo.', '2026-10-12 11:00:00.000000', 'Parâmetros ideais para corais SPS e LPS. Manter rotina de dosagem Balling e TPA quinzenal.', NULL, 8.5, 1380, 5, 0, 8.3, 0.03, 1.025, 0, 25.5, '2026-10-12 11:00:00.000000', 1);
INSERT INTO public.water_parameter_tests VALUES (2, 0, NULL, 'Plantas fazendo pearling intenso à tarde. Discos nadando tranquilos.', '2026-10-12 11:00:00.000000', 'Água doce ácida e mole ideal para peixes amazônicos. Manter fertilização de ferro e potássio.', 5, 3, NULL, 10, 0, 6.6, 0.6, NULL, NULL, 28, '2026-10-12 11:00:00.000000', 4);
INSERT INTO public.water_parameter_tests VALUES (3, 0.02, 440, 'Água um pouco turva após introdução de nova rocha.', '2026-10-12 11:00:00.000000', 'Leve pico de amônia. Aplicar Stability por 3 dias e manter skimmer úmido.', NULL, 9, 1390, 20, 0, 8.1, 0.12, 1.026, 0.1, 25.8, '2026-10-12 11:00:00.000000', 6);
INSERT INTO public.water_parameter_tests VALUES (4, 0, 420, 'Torches e hammers com coloração viva e abrindo completamente.', '2026-10-12 11:00:00.000000', 'Equilíbrio iônico e alcalinidade estáveis. Nenhum ajuste corretivo necessário.', NULL, 8, 1340, 8, 0, 8.2, 0.04, 1.025, 0, 25.2, '2026-10-12 11:00:00.000000', 7);
INSERT INTO public.water_parameter_tests VALUES (5, 0, NULL, 'Betta muito ativo construindo ninho de bolhas na superfície.', '2026-10-12 11:00:00.000000', 'Condições da água neutra e límpida com taninos adequados. Excelente saúde.', 6, 4, NULL, 5, 0, 7, 0.2, NULL, NULL, 26.5, '2026-10-12 11:00:00.000000', 9);
INSERT INTO public.water_parameter_tests VALUES (6, 0, 440, 'SPS com pontas de crescimento nítidas em branco e lilás.', '2026-10-12 11:00:00.000000', 'Excelente consumo de cálcio e carbonatos. Elevar levemente a dosagem da bomba.', NULL, 8.2, 1360, 3, 0, 8.3, 0.02, 1.025, 0, 25, '2026-10-12 11:00:00.000000', 15);

